SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='f990310b-2767-5520-9990-d2d0ade88dfb'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('9ee29d1a-ae6c-50cf-a370-cc43dd36618e','5b483e5d-21f4-5801-ad30-11fd717e32df')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='f990310b-2767-5520-9990-d2d0ade88dfb'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='f990310b-2767-5520-9990-d2d0ade88dfb'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('9ee29d1a-ae6c-50cf-a370-cc43dd36618e','5b483e5d-21f4-5801-ad30-11fd717e32df')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='f990310b-2767-5520-9990-d2d0ade88dfb'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='9ee29d1a-ae6c-50cf-a370-cc43dd36618e' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-05-create-predecessor' AND q.fingerprint='edce2e1f22fca067ed7bfdc7626484dfe246a62e2e5342b2cd877279a6301cc6'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-05-create-predecessor","status":"ok","value":{"customerProfileId":"f990310b-2767-5520-9990-d2d0ade88dfb","userId":"b02aadb1-e2a2-5c50-8a02-1aed2e11bf87","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"9ee29d1a-ae6c-50cf-a370-cc43dd36618e","semanticKey":"customer-controls-customer-05-create-predecessor","fingerprint":"edce2e1f22fca067ed7bfdc7626484dfe246a62e2e5342b2cd877279a6301cc6","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='d234faaa-427f-590f-9ef8-47d22013e88d' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='3a6e7983-6bb3-5277-acdc-08df3a1b5563' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"f990310b-2767-5520-9990-d2d0ade88dfb"},"prior":null,"committed":{"id":"f990310b-2767-5520-9990-d2d0ade88dfb","userId":"b02aadb1-e2a2-5c50-8a02-1aed2e11bf87","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='f990310b-2767-5520-9990-d2d0ade88dfb' AND c.user_id='b02aadb1-e2a2-5c50-8a02-1aed2e11bf87' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-05-create-predecessor' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='6a36bfa4-9a08-5581-9cf4-8b190fdaad79' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"f990310b-2767-5520-9990-d2d0ade88dfb","userId":"b02aadb1-e2a2-5c50-8a02-1aed2e11bf87","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='21c34dfd-82f3-52a0-b3a3-9d07f82965ea' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"b02aadb1-e2a2-5c50-8a02-1aed2e11bf87","track":"customer","customerProfileId":"f990310b-2767-5520-9990-d2d0ade88dfb","sourceCreationRevision":"0","sourceCreationReceipt":"9ee29d1a-ae6c-50cf-a370-cc43dd36618e","semanticKey":"customer_buyer_profile/f990310b-2767-5520-9990-d2d0ade88dfb/default-free-enrollment/v1"}'::jsonb)))=2));
